mapper.select:
select b.SCHEME_DETAIL_ID schemeDetailId,/**方案明细代码**/ b.SEC_TYPE secType, /**证券品种**/ b.SEC_DETAIL_TYPE secDetailType, /**证券细分类**/ b.TRADE_MARKET tradeMarket, /**交易市场**/ b.VALUATION_PRICE valuationPrice, /**估值市价**/ b.VALUATION_PRICE_2 valuationPrice2, /**估值第二市价**/ b.QUOTA_DIGIT quotaDigit, /**行情位数**/ b.QUOTA_DEC_TYPE quotaDecType, /**行情尾数处理**/ b.VALUATION_DATE valuationDate , /**行情日期**/ b.VDATE vdate, /**开始日**/ b.MDATE mdate , /**结束日**/ b.CREATE_USER createUser, /**创建人**/ b.CREATE_DEPT createDept, /**创建部门**/ b.CREATE_TIME createTime, /**创建时间**/ b.UPDATE_USER updateUser, /**更新人**/ b.UPDATE_TIME updateTime /**更新时间**/ from BOK_SHADOW_PRICE_DETAIL b left join BOK_SCHEME_INFO info on b.SCHEME_ID = info.SCH_ID
and b.SCHEME_ID = #{schId}
and b.SEC_TYPE = #{secType}
and b.TRADE_MARKET = #{tradeMarket}
and b.SEC_DETAIL_TYPE = #{secDetailType}
and b.VDATE =to_date(#{vdate}, 'yyyy-MM-dd')

